// Event parser
extension ZoneGroupTopology1Service {
	public struct State: Codable {
		enum CodingKeys: String, CodingKey {
			case availableSoftwareUpdate = "AvailableSoftwareUpdate"
			case zoneGroupState = "ZoneGroupState"
			case thirdPartyMediaServersX = "ThirdPartyMediaServersX"
			case alarmRunSequence = "AlarmRunSequence"
			case museHouseholdId = "MuseHouseholdId"
			case zoneGroupName = "ZoneGroupName"
			case zoneGroupID = "ZoneGroupID"
			case zonePlayerUUIDsInGroup = "ZonePlayerUUIDsInGroup"
			case areasUpdateID = "AreasUpdateID"
			case sourceAreasUpdateID = "SourceAreasUpdateID"
			case netsettingsUpdateID = "NetsettingsUpdateID"
		}

		public var availableSoftwareUpdate: String?
		public var zoneGroupState: String?
		public var thirdPartyMediaServersX: String?
		public var alarmRunSequence: String?
		public var museHouseholdId: String?
		public var zoneGroupName: String?
		public var zoneGroupID: String?
		public var zonePlayerUUIDsInGroup: String?
		public var areasUpdateID: String?
		public var sourceAreasUpdateID: String?
		public var netsettingsUpdateID: String?

		public func log(deep: Bool = false, indent: Int = 0) {
			Logger.swiftUPnP.debug("\(Logger.indent(indent))ZoneGroupTopology1ServiceState {")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))availableSoftwareUpdate: '\(availableSoftwareUpdate ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))zoneGroupState: '\(zoneGroupState ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))thirdPartyMediaServersX: '\(thirdPartyMediaServersX ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))alarmRunSequence: '\(alarmRunSequence ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))museHouseholdId: '\(museHouseholdId ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))zoneGroupName: '\(zoneGroupName ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))zoneGroupID: '\(zoneGroupID ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))zonePlayerUUIDsInGroup: '\(zonePlayerUUIDsInGroup ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))areasUpdateID: '\(areasUpdateID ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))sourceAreasUpdateID: '\(sourceAreasUpdateID ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent+1))netsettingsUpdateID: '\(netsettingsUpdateID ?? "nil")'")
			Logger.swiftUPnP.debug("\(Logger.indent(indent))}")
		}
	}

	public func state(xml: Data) throws -> State {
		struct PropertySet: Codable {
			var property: [State]
		}

		let decoder = XMLDecoder()
		decoder.shouldProcessNamespaces = true
		let propertySet = try decoder.decode(PropertySet.self, from: xml)

		return propertySet.property.reduce(State()) { partialResult, property in
			var result = partialResult
			if let availableSoftwareUpdate = property.availableSoftwareUpdate {
				result.availableSoftwareUpdate = availableSoftwareUpdate
			}
			if let zoneGroupState = property.zoneGroupState {
				result.zoneGroupState = zoneGroupState
			}
			if let thirdPartyMediaServersX = property.thirdPartyMediaServersX {
				result.thirdPartyMediaServersX = thirdPartyMediaServersX
			}
			if let alarmRunSequence = property.alarmRunSequence {
				result.alarmRunSequence = alarmRunSequence
			}
			if let museHouseholdId = property.museHouseholdId {
				result.museHouseholdId = museHouseholdId
			}
			if let zoneGroupName = property.zoneGroupName {
				result.zoneGroupName = zoneGroupName
			}
			if let zoneGroupID = property.zoneGroupID {
				result.zoneGroupID = zoneGroupID
			}
			if let zonePlayerUUIDsInGroup = property.zonePlayerUUIDsInGroup {
				result.zonePlayerUUIDsInGroup = zonePlayerUUIDsInGroup
			}
			if let areasUpdateID = property.areasUpdateID {
				result.areasUpdateID = areasUpdateID
			}
			if let sourceAreasUpdateID = property.sourceAreasUpdateID {
				result.sourceAreasUpdateID = sourceAreasUpdateID
			}
			if let netsettingsUpdateID = property.netsettingsUpdateID {
				result.netsettingsUpdateID = netsettingsUpdateID
			}
			return result
		}
	}

	public var stateSubject: AnyPublisher<State, Never> {
		subscribedEventPublisher
			.compactMap { [weak self] in
				guard let self else { return nil }

				return try? self.state(xml: $0)
			}
			.eraseToAnyPublisher()
	}

	public var stateChangeStream: AsyncStream<State> {
		stateSubject.stream
	}
}
